export { default as Toaster } from "./toaster.svelte";
export { default as Toast } from "./toast.svelte";
export {
	createToastManager,
	toast,
	type ToastId,
	type ToastItem,
	type ToastManager,
	type ToastOptions,
	type ToastPromiseOptions,
	type ToastType,
} from "./toast-manager.js";

import { toast as sonner } from "svelte-sonner";
import Toast from "./toast.svelte";
import type { Component } from "svelte";
import type { HTMLButtonAttributes } from "svelte/elements";

export type ToastType = "success" | "info" | "warning" | "error" | "loading";
export type ToastId = string;
export type ToastOptions = {
	id?: ToastId;
	title?: string;
	description?: string;
	type?: ToastType;
	/** Milliseconds before dismissal. Zero keeps the toast open. */
	timeout?: number;
	priority?: "low" | "high";
	actionProps?: Omit<HTMLButtonAttributes, "children"> & { children: string };
	onClose?: () => void;
};
export type ToastItem = ToastOptions & { id: ToastId };
export type PromiseMessage<T> =
	| string
	| Omit<ToastOptions, "id" | "type">
	| ((value: T) => string | Omit<ToastOptions, "id" | "type">);
export type ToastPromiseOptions<T> = {
	loading: string | Omit<ToastOptions, "id" | "type">;
	success: PromiseMessage<T>;
	error: PromiseMessage<unknown>;
};

let managerCount = 0;

/** Adapts the stacked Base UI manager API to svelte-sonner's public custom renderer. */
export function createToastManager() {
	const toasterId = `shadcn-toast-${managerCount++}`;
	let count = 0;
	const records = new Map<ToastId, { item: ToastItem; notify: () => void }>();

	function render(item: ToastItem, notify: () => void) {
		sonner.custom(Toast as Component<{ item: ToastItem; close: () => void }>, {
			id: `${toasterId}:${item.id}`,
			toasterId,
			componentProps: { item, close: () => close(item.id) },
			duration: item.type === "loading" || item.timeout === 0 ? Infinity : item.timeout,
			important: item.priority === "high",
			onDismiss: notify,
			onAutoClose: notify,
		});
	}

	function add(options: ToastOptions): ToastId {
		const id = options.id ?? `${toasterId}-${count++}`;
		// Sonner's state is browser-only; never retain notification data between SSR requests.
		if (typeof window === "undefined") return id;
		const current = records.get(id);
		if (current) {
			update(id, options);
			return id;
		}
		const record = {
			item: { ...options, id },
			notify: () => {
				if (records.get(id) !== record) return;
				records.delete(id);
				record.item.onClose?.();
			},
		};
		records.set(id, record);
		render(record.item, record.notify);
		return id;
	}

	function update(id: ToastId, options: Partial<ToastOptions>): void {
		const record = records.get(id);
		if (!record) return;
		record.item = { ...record.item, ...options, id };
		render(record.item, record.notify);
	}

	function close(id?: ToastId): void {
		const ids = id === undefined ? [...records.keys()] : [id];
		for (const toastId of ids) {
			const record = records.get(toastId);
			if (!record) continue;
			sonner.dismiss(`${toasterId}:${toastId}`);
			record.notify();
		}
	}

	async function promise<T>(
		task: Promise<T> | (() => Promise<T>),
		options: ToastPromiseOptions<T>
	): Promise<T> {
		const loading =
			typeof options.loading === "string" ? { title: options.loading } : options.loading;
		const id = add({ ...loading, type: "loading" });
		function settle(
			message: PromiseMessage<T> | PromiseMessage<unknown>,
			value: T | unknown,
			type: "success" | "error"
		) {
			const result =
				typeof message === "function"
					? (message as (value: unknown) => string | ToastOptions)(value)
					: message;
			// Explicitly clear loading-only fields instead of leaking them into the settled toast.
			update(id, {
				title: undefined,
				description: undefined,
				actionProps: undefined,
				timeout: undefined,
				...(typeof result === "string" ? { title: result } : result),
				type,
			});
		}
		try {
			const result = await (typeof task === "function" ? task() : task);
			settle(options.success, result, "success");
			return result;
		} catch (error) {
			settle(options.error, error, "error");
			throw error;
		}
	}

	return { toasterId, add, update, close, promise };
}

export type ToastManager = ReturnType<typeof createToastManager>;
export const toast = createToastManager();

/* Sonner supplies measurements, pointer capture, timers and focus handling.
     These selectors adapt its public data attributes to shadcn/ui's stack. */
[data-sonner-toaster].base-toast-viewport {
	--width: 384px;
	--gap: 12px;
	right: 16px;
	bottom: 16px;
	left: auto;
	z-index: 50;
	width: min(384px, calc(100vw - 32px));
	max-width: 384px;
	margin: 0;
	font-family: inherit;
	pointer-events: none;
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast] {
	--toast-scale: max(0, calc(1 - var(--index) * 0.1));
	--toast-swipe-x: var(--swipe-amount-x, 0px);
	--toast-swipe-y: var(--swipe-amount-y, 0px);
	--toast-offset-y: calc(var(--offset) * -1);
	--toast-stack-y: calc(
		var(--toast-swipe-y) - var(--index) * 12px - (1 - var(--toast-scale)) *
			var(--front-toast-height)
	);
	width: 100%;
	transform-origin: bottom;
	pointer-events: auto;
	transition:
		transform 500ms cubic-bezier(0.22, 1, 0.36, 1),
		opacity 500ms,
		height 150ms;
	will-change: transform;
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast][data-mounted="false"] {
	transform: translateY(150%);
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-mounted="true"][data-expanded="false"] {
	height: var(--front-toast-height);
	transform: translateX(var(--toast-swipe-x)) translateY(var(--toast-stack-y))
		scale(var(--toast-scale));
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-mounted="true"][data-expanded="true"] {
	height: var(--initial-height);
	transform: translateX(var(--toast-swipe-x))
		translateY(calc(var(--toast-offset-y) + var(--toast-swipe-y)));
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast]::after {
	position: absolute;
	top: 100%;
	left: 0;
	width: 100%;
	height: 13px;
	content: "";
}

.base-toast-viewport [data-slot="toast-content"] {
	transition: opacity 250ms cubic-bezier(0.22, 1, 0.36, 1);
}

.base-toast-viewport [data-front="false"][data-expanded="false"] [data-slot="toast-content"] {
	opacity: 0;
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast][data-visible="false"] {
	pointer-events: none;
	visibility: hidden;
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast][data-swiping="true"] {
	transition: none;
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-removed="true"][data-mounted][data-expanded] {
	opacity: 0;
	transform: translateY(150%);
	transition-duration: 200ms;
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast][data-swipe-out="true"] {
	animation: none;
	opacity: 0;
	transition-duration: 200ms;
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-swipe-out="true"][data-swipe-direction="left"] {
	transform: translateX(calc(var(--toast-swipe-x) - 150%)) translateY(var(--toast-offset-y));
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-swipe-out="true"][data-swipe-direction="right"] {
	transform: translateX(calc(var(--toast-swipe-x) + 150%)) translateY(var(--toast-offset-y));
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-swipe-out="true"][data-swipe-direction="up"] {
	transform: translateY(calc(var(--toast-swipe-y) - 150%));
}

[data-sonner-toaster].base-toast-viewport
	[data-sonner-toast][data-swipe-out="true"][data-swipe-direction="down"] {
	transform: translateY(calc(var(--toast-swipe-y) + 150%));
}

[data-sonner-toaster].base-toast-viewport [data-sonner-toast]:focus-visible [data-slot="toast"] {
	border-color: var(--color-ring);
	outline: 3px solid color-mix(in oklab, var(--color-ring) 50%, transparent);
}

@media (width < 640px) {
	[data-sonner-toaster].base-toast-viewport {
		right: 16px;
		left: 16px;
		width: auto;
		margin-inline: auto;
	}
}

@media (prefers-reduced-motion: reduce) {
	[data-sonner-toaster].base-toast-viewport [data-sonner-toast],
	.base-toast-viewport [data-slot="toast-content"] {
		transition: none;
		animation: none;
	}
}
